// List returns one page of records under parent.
func (r *GraphQLHotelProductRepository) List(ctx context.Context, parent string, in repox.ListInput) ([]*hotel_productv1.HotelProduct, string, error) {
	parentIDs, err := repox.SplitName(parent, "hotels")
	if err != nil {
		return nil, "", err
	}
	// AIP-159: "-" for the parent reads across every parent.
	if parentIDs[len(parentIDs)-1] == "-" {
		return r.list(ctx, in)
	}
	return r.list(ctx, in, resourceql.HotelId.Eq(parentIDs[len(parentIDs)-1]))
}

func (r *GraphQLHotelProductRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*hotel_productv1.HotelProduct, string, error) {
	if !in.ShowDeleted {
		scope = append(scope, resourceql.DeleteTime.IsNull(true))
	}
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	if err := repox.CheckReadMask((*hotel_productv1.HotelProduct)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng := filterx.Hasura[resourceql.HotelproductResource](hotelproduct.HotelProductFilterSpec, r.Svc.Query.Hotelproduct.Resource).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	eng.Via("value_add_inclusions", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Hotelproduct.ValueAddInclusions.List(ctx, valueaddinclusionsql.List().Where(graphql.And(valueaddinclusionsql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("policy_info", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Hotelproduct.PolicyInfos.List(ctx, policyinfosql.List().Where(graphql.And(policyinfosql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*hotel_productv1.HotelProduct, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

